package http

// Backward-compatibility acceptance tests: code generated by previous
// protoc-gen-go-http versions (Gorilla regex patterns, dotted field
// names, per-RPC action registrations through plain Router.Handle) keeps
// working on the ServeMux engine without regeneration, plus the restored
// previous-engine behaviors for duplicate registrations and exact
// trailing-slash/root routes.

import (
	"net/http"
	"net/http/httptest"
	"testing"

	"github.com/apus-run/spine/v3/transport"
)

// oldGenServer registers routes exactly the way the previous generator
// emitted them: one r.Handle call per RPC, Gorilla regex constraints,
// dotted field names, separate registrations per custom action.
func oldGenServer(t *testing.T) (*Server, *[]string) {
	t.Helper()
	hits := &[]string{}
	srv := NewServer()
	r := srv.Route("/")

	// GET /v1/users/{id} — plain variable (unchanged grammar).
	r.Handle("GET", "/v1/users/{id}", func(ctx Context) error {
		*hits = append(*hits, "get-user:"+ctx.Vars().Get("id"))
		return nil
	})
	// GET /v1/books/{book.name} — dotted plain variable.
	r.Handle("GET", "/v1/books/{book.name}", func(ctx Context) error {
		*hits = append(*hits, "get-book:"+ctx.Vars().Get("book.name"))
		return nil
	})
	// GET /v1/{name=projects/*/books/*} — composite resource name.
	r.Handle("GET", "/v1/{name=projects/*/books/*}", func(ctx Context) error {
		*hits = append(*hits, "get-resource:"+ctx.Vars().Get("name"))
		return nil
	})
	// Old regex forms: {name:messages/[^/]+} and {name:messages/.*}.
	r.Handle("GET", "/v1/regex/{name:messages/[^/]+}", func(ctx Context) error {
		*hits = append(*hits, "regex-single:"+ctx.Vars().Get("name"))
		return nil
	})
	r.Handle("GET", "/v1/star/{name:messages/.*}", func(ctx Context) error {
		*hits = append(*hits, "regex-multi:"+ctx.Vars().Get("name"))
		return nil
	})
	// Custom actions as separate registrations (old generated shape):
	// both compile to the same structural pattern and must aggregate.
	r.Handle("POST", "/v1/{name=books/*}:publish", func(ctx Context) error {
		*hits = append(*hits, "publish:"+ctx.Vars().Get("name"))
		return nil
	})
	r.Handle("POST", "/v1/{name=books/*}:archive", func(ctx Context) error {
		*hits = append(*hits, "archive:"+ctx.Vars().Get("name"))
		return nil
	})
	r.Handle("POST", "/v1/{name=books/*}", func(ctx Context) error {
		*hits = append(*hits, "update:"+ctx.Vars().Get("name"))
		return nil
	})
	return srv, hits
}

func TestCompat_OldGeneratedRoutes(t *testing.T) {
	srv, hits := oldGenServer(t)
	cases := []struct {
		method, path string
		code         int
		want         string
	}{
		{http.MethodGet, "/v1/users/42", 200, "get-user:42"},
		{http.MethodGet, "/v1/books/hobbit", 200, "get-book:hobbit"},
		{http.MethodGet, "/v1/projects/acme/books/7", 200, "get-resource:projects/acme/books/7"},
		{http.MethodGet, "/v1/regex/messages/a", 200, "regex-single:messages/a"},
		{http.MethodGet, "/v1/regex/messages/a/b", 404, ""},          // [^/]+ stays single-segment
		{http.MethodGet, "/v1/star/messages/a/b", 200, "regex-multi:messages/a/b"},
		{http.MethodPost, "/v1/books/42:publish", 200, "publish:books/42"},
		{http.MethodPost, "/v1/books/42:archive", 200, "archive:books/42"},
		{http.MethodPost, "/v1/books/42", 200, "update:books/42"},
		{http.MethodPost, "/v1/books/42:explode", 404, ""},           // unknown action
		{http.MethodPost, "/v1/users/42", 405, ""},                   // method mismatch keeps 405 + Allow
	}
	for _, c := range cases {
		*hits = nil
		req := httptest.NewRequest(c.method, c.path, nil)
		w := httptest.NewRecorder()
		srv.ServeHTTP(w, req)
		if w.Code != c.code {
			t.Fatalf("%s %s: want %d, got %d", c.method, c.path, c.code, w.Code)
		}
		if c.want == "" {
			if len(*hits) != 0 {
				t.Fatalf("%s %s: no handler expected, got %v", c.method, c.path, *hits)
			}
			continue
		}
		if len(*hits) != 1 || (*hits)[0] != c.want {
			t.Fatalf("%s %s: want [%s], got %v", c.method, c.path, c.want, *hits)
		}
	}

	// Transport metadata carries the ORIGINAL template of the selected
	// binding, including aggregated actions.
	var op string
	srv2 := NewServer()
	srv2.Route("/").Handle("POST", "/v1/{name=books/*}:publish", func(ctx Context) error {
		if tr, ok := transport.FromServerContext(ctx); ok {
			if htr, ok := tr.(*Transport); ok {
				op = htr.PathTemplate()
			}
		}
		return nil
	})
	w := httptest.NewRecorder()
	srv2.ServeHTTP(w, httptest.NewRequest(http.MethodPost, "/v1/books/9:publish", nil))
	if w.Code != 200 || op != "/v1/{name=books/*}:publish" {
		t.Fatalf("aggregated binding metadata: %d %q", w.Code, op)
	}
}

// Wildcards bound under different field names at the same position keep
// the first registration (previous engine behavior) and still serve the
// first route's semantics.
func TestCompat_StructuralDuplicateNames(t *testing.T) {
	srv := NewServer()
	srv.HandleFunc("/v1/{name}", func(w http.ResponseWriter, r *http.Request) {
		_, _ = w.Write([]byte("first:" + r.PathValue("name")))
	})
	srv.HandleFunc("/v1/{id}", func(w http.ResponseWriter, r *http.Request) {
		_, _ = w.Write([]byte("second"))
	})
	w := httptest.NewRecorder()
	srv.ServeHTTP(w, httptest.NewRequest(http.MethodGet, "/v1/x", nil))
	if w.Code != 200 || w.Body.String() != "first:x" {
		t.Fatalf("structural duplicate: %d %q", w.Code, w.Body.String())
	}
}

// Exact registrations ending in "/" (including the root) match only that
// path; subtree behavior stays with HandlePrefix (previous engine
// semantics restored).
func TestCompat_ExactRootAndTrailingSlash(t *testing.T) {
	srv := NewServer()
	srv.HandleFunc("/", func(w http.ResponseWriter, r *http.Request) {
		_, _ = w.Write([]byte("root"))
	})
	srv.HandleFunc("/api/", func(w http.ResponseWriter, r *http.Request) {
		_, _ = w.Write([]byte("api-slash"))
	})
	srv.HandlePrefix("/static", http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		_, _ = w.Write([]byte("static"))
	}))

	cases := []struct {
		path string
		code int
		body string
	}{
		{"/", 200, "root"},
		{"/other", 404, ""},          // root is exact again, not a catch-all
		{"/api/", 200, "api-slash"},
		{"/api/x", 404, ""},          // trailing-slash route is exact
		{"/static", 200, "static"},   // prefix keeps covering the bare prefix
		{"/static/a/b.css", 200, "static"},
		{"/staticX", 404, ""},        // segment boundary (D3, unchanged)
	}
	for _, c := range cases {
		req := httptest.NewRequest(http.MethodGet, c.path, nil)
		w := httptest.NewRecorder()
		srv.ServeHTTP(w, req)
		if w.Code != c.code || (c.body != "" && w.Body.String() != c.body) {
			t.Fatalf("%s: want %d %q, got %d %q", c.path, c.code, c.body, w.Code, w.Body.String())
		}
	}

	// "/api" bridges to the exact "/api/" route with the query preserved;
	// for "{$}"-terminated patterns the ServeMux itself emits this redirect
	// (301 on Go 1.25.x, 307 on 1.26+ — same class as subtree redirects,
	// passed through unmodified per D5).
	req := httptest.NewRequest(http.MethodGet, "/api?q=1", nil)
	w := httptest.NewRecorder()
	srv.ServeHTTP(w, req)
	if w.Code != http.StatusMovedPermanently && w.Code != http.StatusTemporaryRedirect {
		t.Fatalf("bridge to exact trailing-slash route: %d", w.Code)
	}
	if loc := w.Header().Get("Location"); loc != "/api/?q=1" {
		t.Fatalf("bridge location: %q", loc)
	}
}

// The new generator path (HandleBindings) coexists with compat
// registrations on the same server.
func TestCompat_MixedRegistrations(t *testing.T) {
	srv := NewServer()
	r := srv.Route("/")
	r.Handle("GET", "/v1/old/{id:[0-9]+}", func(ctx Context) error {
		return ctx.String(200, "old")
	})
	r.HandleBindings("GET", "/v1/new/{p0}",
		RouteBinding{
			Template: "/v1/new/{id}",
			Bindings: []PathBinding{{Field: "id", Segments: []string{"*"}, Wildcards: []string{"p0"}}},
			Handler: func(ctx Context) error {
				return ctx.String(200, "new:"+ctx.Vars().Get("id"))
			},
		})
	for _, c := range []struct{ path, want string }{
		{"/v1/old/7", "old"},
		{"/v1/old/x", ""}, // validator rejects
		{"/v1/new/7", "new:7"},
	} {
		req := httptest.NewRequest(http.MethodGet, c.path, nil)
		w := httptest.NewRecorder()
		srv.ServeHTTP(w, req)
		if c.want == "" {
			if w.Code != 404 {
				t.Fatalf("%s: want 404, got %d", c.path, w.Code)
			}
			continue
		}
		if w.Code != 200 || w.Body.String() != c.want {
			t.Fatalf("%s: want %s, got %d %q", c.path, c.want, w.Code, w.Body.String())
		}
	}
}
